import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    # Create the torso
    torso = sandbox.add_beam(
        x=10.0, y=2.5, width=0.2, height=0.2, angle=0, density=1.0
    )

    # Create left leg
    left_leg = sandbox.add_beam(
        x=9.5, y=2.5, width=0.2, height=0.5, angle=0, density=1.0
    )

    # Create right leg
    right_leg = sandbox.add_beam(
        x=10.5, y=2.5, width=0.2, height=0.5, angle=0, density=1.0
    )

    # Connect legs to torso with pivot joints
    joint_left = sandbox.add_joint(
        torso, left_leg, anchor_point=(9.5, 2.5), type='pivot'
    )
    joint_right = sandbox.add_joint(
        torso, right_leg, anchor_point=(10.5, 2.5), type='pivot'
    )

    # Set material properties for friction
    sandbox.set_material_properties(torso, friction=0.008, restitution=0.1)
    sandbox.set_material_properties(left_leg, friction=0.008, restitution=0.1)
    sandbox.set_material_properties(right_leg, friction=0.008, restitution=0.1)

    return {"body": torso, "joints": [joint_left, joint_right]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    # Drive the left and right legs in opposite directions to simulate forward motion
    sandbox.set_motor(joints[0], motor_speed=-2.0, max_torque=100.0)  # Left leg
    sandbox.set_motor(joints[1], motor_speed=2.0, max_torque=100.0)   # Right leg
